async def act(page):
    # No knowledge_base helper functions are available (the <functions> list is empty),
    # so interact directly with Playwright.

    # 1) Open Prices tab and set Price = 169.99
    try:
        await page.get_by_role("link", name="Prices").click()
        await page.wait_for_timeout(500)
    except Exception:
        # If Prices tab not present or already active, continue
        pass

    try:
        await page.get_by_label("Price").fill("169.99")
    except Exception:
        try:
            await page.get_by_label("Product Price").fill("169.99")
        except Exception:
            # Fallback: try to fill a textbox that has 'Price' in its accessible name
            try:
                price_box = page.get_by_role("textbox").filter(has_text="Price")
                await price_box.first.fill("169.99")
            except Exception:
                pass

    # 2) Set attribute Color = Blue
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="Blue")
    except Exception:
        try:
            await page.get_by_label("Color").select_option(label="Blue")
        except Exception:
            try:
                await page.get_by_label("Color").fill("Blue")
            except Exception:
                pass

    # 3) Set attribute Size = 34
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="34")
    except Exception:
        try:
            await page.get_by_label("Size").select_option(label="34")
        except Exception:
            try:
                await page.get_by_label("Size").fill("34")
            except Exception:
                pass

    # 4) Open Inventory tab and set Qty = 42 and Stock Availability = In Stock
    try:
        await page.get_by_role("link", name="Inventory").click()
        await page.wait_for_timeout(500)
    except Exception:
        try:
            await page.get_by_role("tab", name="Inventory").click()
            await page.wait_for_timeout(500)
        except Exception:
            pass

    # Set quantity
    qty_set = False
    for label in ("Qty", "Quantity", "Qty *"):
        try:
            await page.get_by_label(label).fill("42")
            qty_set = True
            break
        except Exception:
            continue

    if not qty_set:
        try:
            txts = page.get_by_role("textbox")
            count = await txts.count()
            for i in range(min(6, count)):
                try:
                    await txts.nth(i).fill("42")
                    break
                except Exception:
                    continue
        except Exception:
            pass

    # Ensure In Stock
    try:
        await page.get_by_role("combobox", name="Stock Availability").select_option(label="In Stock")
    except Exception:
        try:
            await page.get_by_role("radio", name="In Stock").check()
        except Exception:
            try:
                await page.get_by_label("Stock Availability").select_option(label="In Stock")
            except Exception:
                pass

    # 5) Save product (last action because it navigates away)
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        try:
            await page.get_by_text("Save").click()
        except Exception:
            try:
                await page.keyboard.press("Enter")
            except Exception:
                pass
